import java.io.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import org.millenaire.common.buildingplan.BuildingBlockStateIO;import org.millenaire.common.utilities.LegacyBlockStates;
public class ConstructionStateCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static byte[] record(BlockState s,byte m,byte special)throws Exception{var bytes=new ByteArrayOutputStream();BuildingBlockStateIO.write(new DataOutputStream(bytes),s,m,special);return bytes.toByteArray();}static BuildingBlockStateIO.Entry read(byte[] bytes)throws Exception{return BuildingBlockStateIO.read(new DataInputStream(new ByteArrayInputStream(bytes)));}static void reject(byte[] bytes)throws Exception{try{read(bytes);throw new AssertionError("Invalid input accepted");}catch(IOException expected){}}
 public static void main(String[] args)throws Exception{net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();int count=0;var chain=new ByteArrayOutputStream();var out=new DataOutputStream(chain);
 for(Block block:Registry.BLOCK)for(BlockState state:block.getStateDefinition().getPossibleStates()){var decoded=read(record(state,(byte)-1,(byte)43));check(decoded.state().equals(state)&&decoded.markerMetadata()==-1&&decoded.special()==43,"Round trip "+state);BuildingBlockStateIO.write(out,state,(byte)0,(byte)0);count++;}
 var in=new DataInputStream(new ByteArrayInputStream(chain.toByteArray()));for(int i=0;i<count;i++)BuildingBlockStateIO.read(in);check(in.available()==0,"Record boundaries exact");
 for(int m=0;m<8;m++){var state=BuildingBlockStateIO.fromMarker(Blocks.OAK_STAIRS,m);check(BuildingBlockStateIO.markerMetadata(state)==m,"Stair marker mapping");}for(int m=2;m<=5;m++){var state=BuildingBlockStateIO.fromMarker(Blocks.LADDER,m);check(BuildingBlockStateIO.markerMetadata(state)==m,"Ladder marker mapping");}
 var bytes=new ByteArrayOutputStream();out=new DataOutputStream(bytes);out.writeInt(17);out.writeByte(7);out.writeByte(0);check(read(bytes.toByteArray()).state().equals(LegacyBlockStates.fromName("minecraft:log",7)),"Legacy log species and axis");
 bytes=new ByteArrayOutputStream();out=new DataOutputStream(bytes);out.writeInt(-9999);reject(bytes.toByteArray());bytes=new ByteArrayOutputStream();out=new DataOutputStream(bytes);out.writeInt(4095);out.writeByte(0);out.writeByte(0);reject(bytes.toByteArray());
 for(String name:new String[]{"missing:stone","minecraft:oak_log"}){bytes=new ByteArrayOutputStream();out=new DataOutputStream(bytes);out.writeInt(-2975);var tag=new CompoundTag();tag.putString("Name",name);var props=new CompoundTag();props.putString("axis","invalid");tag.put("Properties",props);NbtIo.write(tag,out);out.writeByte(0);out.writeByte(0);reject(bytes.toByteArray());}
 byte[] valid=record(Blocks.OAK_STAIRS.defaultBlockState(),(byte)0,(byte)0);reject(java.util.Arrays.copyOf(valid,valid.length-1));
 System.out.println("PASS: "+count+" vanilla states round-trip in construction binary codec; concatenated records, special/marker bytes, stair/ladder mappings, old log metadata, unsupported IDs/versions/properties and truncated data. Real codec and NBT; no world migration or block placement tested.");}}
